import { readFile } from 'node:fs/promises'
import {
    validateDiagnostic,
    createProject,
    runTestOnFunction,
    FluentXmlFluentTest,
    XmlFluentXmlTest,
    xml,
} from '../test-utils'
import { path, ts } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

const SCOPE = 'x_cs'
const project = createProject({ config: { scope: SCOPE } })

interface TestCase {
    tsFile: string
    xmlFile: string
}

const testCasesDSLtoXML: TestCase[] = [
    {
        tsFile: './create/clientscript.now.ts',
        xmlFile: './create/clientscript-create-result.xml',
    },
    {
        tsFile: './create/clientscript0.now.ts',
        xmlFile: './create/cs0-create-result.xml',
    },
    {
        tsFile: './create/clientscript1.now.ts',
        xmlFile: './create/cs1-create-result.xml',
    },
    {
        tsFile: './create/clientscript2.now.ts',
        xmlFile: './create/cs2-create-result.xml',
    },
    {
        tsFile: './create/clientscript5.now.ts',
        xmlFile: './create/cs5-create-result.xml',
    },
]

const testCasesXMLtoDSL: TestCase[] = [
    {
        xmlFile: './update/clientscript.xml',
        tsFile: './update/clientscript-update.now.ts',
    },
    {
        xmlFile: './update/cs0-update.xml',
        tsFile: './update/cs0-update.now.ts',
    },
    {
        xmlFile: './create/cs0-create-result.xml',
        tsFile: './update/clientscript0.now.ts',
    },
    {
        xmlFile: './create/cs1-create-result.xml',
        tsFile: './update/clientscript1.now.ts',
    },
    {
        xmlFile: './create/cs2-create-result.xml',
        tsFile: './update/clientscript2.now.ts',
    },
    {
        xmlFile: './create/cs5-create-result.xml',
        tsFile: './update/clientscript5.now.ts',
    },
]
describe('Client Script plugin', () => {
    describe('Diagnostics', () => {
        test('shows diagnostic when using an import statement in onLoad scripts', async () => {
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid Table import
                ClientScript({
                    $id: 'my_scripts',
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    //OnLoad type, Fail because of import statement in Script
                    type: 'onLoad',
                    script: `import { showInfoMessage } from './utilities';
    function onLoad() { showInfoMessage("hello"); }`,
                    active: true,
                    applies_extended: false,
                    description: 'cool',
                    messages: '',
                    isolate_script: false,
                    ui_type: 'all',
                    global: false,
                    view: 'app_task_view',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.NoSubstitutionTemplateLiteral,
                'Client side scripts cannot import or require modules.'
            )
        })

        test('shows diagnostic when using an import statement inside scripts with Now.include syntax', async () => {
            project.addFile({
                path: 'cs.js',
                content: `import { showInfoMessage } from './utilities';
    function onLoad() { showInfoMessage("hello"); }`,
            })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid Table import
                ClientScript({
                    $id: 'my_scripts',
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    //OnLoad type, Fail because of import statement in Script
                    type: 'onLoad',
                    script: Now.include('./cs.js'),
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    uiType: 'all',
                    global: false,
                    view: 'app_task_view',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.CallExpression,
                'Client side scripts cannot import or require modules.'
            )
        })

        test('shows diagnostic when view is set with no type', async () => {
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid Table import
                ClientScript({
                    $id: 'my_scripts',
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    script: '',
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    uiType: 'all',
                    view: 'app_task_view',
                    field: 'state',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.StringLiteral,
                'Field values are allowed only when type is set to onChange or onCellEdit'
            )
        })

        test('hint diagnostic created when there is use of snake case in ClientScript', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            project.addFile({
                path: 'index.now.ts',
                content: `
                             import { ClientScript } from '@servicenow/sdk/core'
        
        ClientScript({
                    $id: 'my_scripts',
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    script: '',
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    type: 'onChange',
                    ui_type: 'all',
                    field: 'state',
                })`,
            })
            const diagnostics = await project.getDiagnostics()
            expect(diagnostics).toHaveLength(1)
            validateDiagnostic(
                diagnostics,
                ts.SyntaxKind.StringLiteral,
                `The property 'ui_type' is deprecated, use 'uiType' instead.`
            )
        })

        test('DEF0730336: no diagnostic errors created when field is set with values not part of the table schema', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            project.addFile({
                path: 'index.now.ts',
                content: `
                             import { ClientScript, Table, StringColumn } from '@servicenow/sdk/core'

        export const x_cs_some_table = Table({
            name: 'x_cs_some_table',
            schema: {
                state: StringColumn({}),
            },
        })
        
        ClientScript({
                    $id: 'my_scripts',
                    name: 'my_scripts',
                    table: 'x_cs_some_table',
                    script: '',
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    type: 'onChange',
                    uiType: 'all',
                    field: 'undeclared', //no diagnostic error
                })`,
            })
            const diagnostics = await project.getDiagnostics()
            expect(diagnostics).toHaveLength(0)
        })
    })
    describe('Fluent to XML', () => {
        test.each(testCasesDSLtoXML)('creates XML from %s', async ({ tsFile, xmlFile }) => {
            const project = createProject({ config: { scope: SCOPE } })
            project.addFile(`${__dirname}/create/script.now.ts`)
            const file = project.addFile({
                path: `${__dirname}/create/clientscript.now.ts`,
                content: await readFile(`${__dirname}/${tsFile}`, 'utf8'),
            })
            project.registerExplicitId('sys_script_client', 'script-id', 'script-id')
            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            const expected = await readFile(`${__dirname}/${xmlFile}`, 'utf8')
            expect(output[0].content.trim()).toEqual(expected.trim())
        })
    })
    describe('XML to Fluent', () => {
        test.each(testCasesXMLtoDSL)('creates DSL from %s', async ({ xmlFile, tsFile }) => {
            const project = createProject({ config: { scope: SCOPE } })
            const result = await project.transform(`${__dirname}/${xmlFile}`)
            const content = result.changedFiles[0]?.getContent()
            const expected = await readFile(`${__dirname}/${tsFile}`, 'utf8')
            expect(content.trim()).toEqual(expected.trim())
        })

        test('DEF0730336: transform removes the field value when type is not one of onCellEdit or onChange', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            project.registerExplicitId('sys_script_client', 'my_scripts', '40d145bffd224a09f6c60a7676d985e6')
            project.addFile({
                path: 'index.now.ts',
                content: `
                import { ClientScript } from '@servicenow/sdk/core'

                ClientScript({
                    $id: Now.ID['my_scripts'],
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    script: '',
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    type: 'onCellEdit',
                    uiType: 'all',
                    field: 'state',
                })`,
            })
            const result = await project.transform({
                path: 'cs.xml',
                content: `
<?xml version="1.0"?>
<unload>
  <sys_script_client action="INSERT_OR_UPDATE">
    <sys_id>40d145bffd224a09f6c60a7676d985e6</sys_id>
    <sys_scope display_value="x_test">x_test01234567890123456789012345</sys_scope>
    <table>x_cs_table</table>
    <name>my_scripts</name>
    <active>true</active>
    <applies_extended>false</applies_extended>
    <ui_type>10</ui_type>
    <description>cool</description>
    <messages/>
    <isolate_script>false</isolate_script>
    <global>true</global>
    <type>onLoad</type>
    <script><![CDATA[]]></script>
    <field>state</field>
    <sys_class_name>sys_script_client</sys_class_name>
  </sys_script_client>
</unload>
            `,
            })
            const diagnostics = await project.getDiagnostics()
            expect(diagnostics).toHaveLength(0)
            expect(result.changedFiles).toHaveLength(1)
            expect(result.changedFiles[0].getContent()).toBe(`import { ClientScript } from '@servicenow/sdk/core'

ClientScript({
    $id: Now.ID['my_scripts'],
    name: 'my_scripts',
    table: 'x_cs_table',
    script: '',
    active: true,
    appliesExtended: false,
    description: 'cool',
    messages: '',
    isolateScript: false,
    type: 'onLoad',
    uiType: 'all',
})
`)
        })

        test('DEF0730336: transform removes the field value when unset', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            project.registerExplicitId('sys_script_client', 'my_scripts', '40d145bffd224a09f6c60a7676d985e6')
            project.addFile({
                path: 'index.now.ts',
                content: `
                import { ClientScript } from '@servicenow/sdk/core'

                ClientScript({
                    $id: Now.ID['my_scripts'],
                    name: 'my_scripts',
                    table: 'x_cs_table',
                    script: '',
                    active: true,
                    appliesExtended: false,
                    description: 'cool',
                    messages: '',
                    isolateScript: false,
                    type: 'onCellEdit',
                    uiType: 'all',
                    field: 'state',
                })`,
            })
            const result = await project.transform({
                path: 'cs.xml',
                content: `
<?xml version="1.0"?>
<unload>
  <sys_script_client action="INSERT_OR_UPDATE">
    <sys_id>40d145bffd224a09f6c60a7676d985e6</sys_id>
    <sys_scope display_value="x_test">x_test01234567890123456789012345</sys_scope>
    <table>x_cs_table</table>
    <name>my_scripts</name>
    <active>true</active>
    <applies_extended>false</applies_extended>
    <ui_type>10</ui_type>
    <description>cool</description>
    <messages/>
    <isolate_script>false</isolate_script>
    <global>true</global>
    <type>onCellEdit</type>
    <script><![CDATA[]]></script>
    <field/>
    <sys_class_name>sys_script_client</sys_class_name>
  </sys_script_client>
</unload>
            `,
            })
            const diagnostics = await project.getDiagnostics()
            expect(diagnostics).toHaveLength(0)
            expect(result.changedFiles).toHaveLength(1)
            expect(result.changedFiles[0].getContent()).toBe(`import { ClientScript } from '@servicenow/sdk/core'

ClientScript({
    $id: Now.ID['my_scripts'],
    name: 'my_scripts',
    table: 'x_cs_table',
    script: '',
    active: true,
    appliesExtended: false,
    description: 'cool',
    messages: '',
    isolateScript: false,
    type: 'onCellEdit',
    uiType: 'all',
})
`)
        })
    })

    describe('Fluent => XML => Fluent', () => {
        test('file can round-trip correctly', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const id = roundTripTest.addId('sys_script_client', 'script-id')
            roundTripTest.addExpectedXmlFileNames(`sys_script_client_${id}.xml`)

            roundTripTest.addFluentFragment(
                `
import { ClientScript } from '@servicenow/sdk/core'

//OnLoad type, using script tag to define script, active left empty
ClientScript({
    $id: Now.ID['script-id'],
    name: 'my_scripts',
    table: 'x_cs_table',
    script: 'function onLoad(){ g_form.addInfoMessage("hello") }',
    appliesExtended: false,
    description: 'cool',
    global: false,
    messages: '',
    isolateScript: false,
    uiType: 'desktop',
    view: 'app_task_view',
    type: 'onLoad',
})
`
            )

            await roundTripTest.verify()
        })

        test('can transform backtick characters in code', async () => {
            const project = new Project()

            const {
                changedFiles: [file],
            } = await project.transform({
                path: 'client_script.xml',
                content: `
<?xml version="1.0"?>
<record_update>
  <sys_script_client action="INSERT_OR_UPDATE">
    <sys_id>8ac1d655b46f452f9aefe9a87557a194</sys_id>
    <sys_scope display_value="x_cs">11111111111111111111111111111111</sys_scope>
    <active>true</active>
    <applies_extended>true</applies_extended>
    <description>cool</description>
    <field/>
    <global>false</global>
    <isolate_script>true</isolate_script>
    <messages/>
    <name>my_scripts</name>
    <script><![CDATA[function onLoad() {
    g_form.addInfoMessage(\`cool backticks\`)
}]]></script>
    <table>x_cs_table</table>
    <type>onLoad</type>
    <ui_type>10</ui_type>
    <view/>
  </sys_script_client>
</record_update>
                    `,
            })

            const scriptFileContent = project
                .getFiles()
                .find((file) =>
                    file
                        .getPath()
                        .includes('client-script/sys_script_client_8ac1d655b46f452f9aefe9a87557a194.client.js')
                )
            expect(scriptFileContent.getContent()).toContain(`function onLoad() {
    g_form.addInfoMessage(\`cool backticks\`)
}`)
            expect(file.getContent()).toContain(
                `script: Now.include('./sys_script_client_8ac1d655b46f452f9aefe9a87557a194.client.js')`
            )
        })

        test('ClientScript with snake_case gets updated to camelCase on round-trip', async () => {
            const project = createProject({ rootDir: __dirname })
            project.registerExplicitId('sys_script_client', 'script-id')

            const csFile = project.addFile({
                path: 'cs.now.ts',
                content: `import { ClientScript } from '@servicenow/sdk/core'

ClientScript({
    $id: Now.ID['script-id'],
    name: 'my_scripts',
    table: 'x_cs_table',
    script: 'function onLoad(){ g_form.addInfoMessage("hello") }',
    applies_extended: false,
    description: 'cool',
    global: false,
    messages: '',
    isolate_script: false,
    ui_type: 'desktop',
    view: 'app_task_view',
    type: 'onLoad',
})
`,
            })

            const xmlOutputs = await csFile.getOutput()
            const { changedFiles } = await project.transform(xmlOutputs)
            expect(await project.getDiagnostics()).toHaveLength(0)
            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('cs.now.ts')
            expect(changedFiles[0].getContent()).toBe(`import { ClientScript } from '@servicenow/sdk/core'

ClientScript({
    $id: Now.ID['script-id'],
    name: 'my_scripts',
    table: 'x_cs_table',
    script: 'function onLoad(){ g_form.addInfoMessage("hello") }',
    appliesExtended: false,
    description: 'cool',
    global: false,
    messages: '',
    isolateScript: false,
    uiType: 'desktop',
    view: 'app_task_view',
    type: 'onLoad',
})
`)
        })
    })

    describe('XML => Fluent => XML', () => {
        test('files can round-trip correctly', async () => {
            const project = createProject({
                rootDir: __dirname,
                config: { scope: SCOPE },
            })
            const originalFiles = [
                {
                    path: 'sys_script_client_8ac1d655b46f452f9aefe9a87557a194.xml',
                    content: xml`<?xml version="1.0"?>
<record_update>
  <sys_script_client action="INSERT_OR_UPDATE">
    <sys_id>8ac1d655b46f452f9aefe9a87557a194</sys_id>
    <sys_scope display_value="x_cs">11111111111111111111111111111111</sys_scope>
    <active>true</active>
    <applies_extended>true</applies_extended>
    <description>cool</description>
    <field/>
    <global>false</global>
    <isolate_script>true</isolate_script>
    <messages/>
    <name>my_scripts</name>
    <script><![CDATA[function onLoad() {
    g_form.addInfoMessage('cool')
}]]></script>
    <table>x_cs_table</table>
    <type>onLoad</type>
    <ui_type>10</ui_type>
    <view/>
  </sys_script_client>
</record_update>
`,
                },
            ]
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })

        test('handles ]]> in script CDATA properly', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            project.registerExplicitId('sys_script_client', 'cdata_test')

            const file = project.addFile({
                path: 'client-cdata.now.ts',
                content: `import { ClientScript } from '@servicenow/sdk/core'

ClientScript({
    $id: Now.ID['cdata_test'],
    name: 'CDATA Test Client Script',
    table: 'incident',
    script: 'console.log("Client script with ]]> sequence");',
    type: 'onLoad'
})`,
            })

            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            // Verify that ]]> is properly escaped in CDATA section
            expect(output[0].content).toContain(
                '<script><![CDATA[console.log("Client script with ]]]]><![CDATA[> sequence");]]></script>'
            )
        })
    })
})
